const PASSWORD='FORTRESS',ARCHIVE_PASSWORD='baron',MAX_ATTEMPTS=5,ROW_WIDTH=12;
const candidates=['FORTRESS','FORESTER','FORTUNES','FOSTERED','SHORTENS','SORTABLE','FORMLESS','FEARLESS','RESTORES','FIREWALL','PASSWORD','STRONGER'];
const junk=['!','@','#','$','%','^','&','*','-','+','=','?','/','\\',';',':','.'];
let attempts=MAX_ATTEMPTS,used=new Set(),duds=new Set(),revealed=new Set(),hintUses={remove:0,reveal:0,trap:0},dumpRefreshed=false,accessGranted=false;
const dump=document.getElementById('memoryDump'),log=document.getElementById('hackLog'),blocks=document.getElementById('attemptBlocks');
const hints=[{text:'(^-)',type:'remove'},{text:'(.#)',type:'reveal'},{text:'(?;)',type:'trap'}];
function similarity(word){return [...word].filter((c,i)=>c===PASSWORD[i]).length}
function addLog(text,cls=''){const p=document.createElement('p');p.className=cls;p.textContent='> '+text;log.appendChild(p);log.scrollTop=log.scrollHeight}
function shuffle(list){for(let i=list.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]]}return list}
function junkStream(count){return Array.from({length:count},()=>`<span class="token">${junk[Math.floor(Math.random()*junk.length)]}</span>`).join('')}
function wordToken(word){return `<button class="token word${used.has(word)||duds.has(word)?' used':''}" data-word="${word}">${word}</button>`}
function build(){dump.innerHTML='';const words=shuffle([...candidates]),hintPool=shuffle([...hints,...hints]),wordRows=new Map(),hintRows=new Map();for(let band=0;band<6;band++){const rows=shuffle([0,1,2,3].map(n=>band*4+n));wordRows.set(rows[0],words.pop());wordRows.set(rows[1],words.pop());hintRows.set(rows[2],hintPool.pop())}const hintSeen={remove:0,reveal:0,trap:0};for(let i=0;i<24;i++){const addr=(0xF400+i*ROW_WIDTH).toString(16).toUpperCase();let stream;if(wordRows.has(i)){const word=wordRows.get(i),room=ROW_WIDTH-word.length,offset=Math.floor(Math.random()*(room+1));stream=junkStream(offset)+wordToken(word)+junkStream(room-offset)}else if(hintRows.has(i)){const hint=hintRows.get(i),room=ROW_WIDTH-hint.text.length,offset=Math.floor(Math.random()*(room+1)),occurrence=hintSeen[hint.type]++,spent=occurrence<hintUses[hint.type];stream=junkStream(offset)+`<button class="token bracket${spent?' used':''}" data-hint="${hint.type}">${hint.text}</button>`+junkStream(room-offset)}else stream=junkStream(ROW_WIDTH);dump.insertAdjacentHTML('beforeend',`<div class="dump-line"><span class="addr">0x${addr}</span><span>${stream}</span></div>`)}}
function updateAttempts(){blocks.textContent=Array.from({length:MAX_ATTEMPTS},(_,i)=>i<attempts?'■':'□').join(' ')}
function lockIfEmpty(){if(attempts>0)return false;addLog('ТЕРМИНАЛ ЗАБЛОКИРОВАН','fail');document.querySelectorAll('.word,.bracket').forEach(x=>x.classList.add('used'));return true}
function choose(word,button){if(used.has(word)||attempts<=0||accessGranted)return;used.add(word);button.classList.add('used');addLog(word);if(word===PASSWORD){window.TerminalAudio?.success();accessGranted=true;document.querySelectorAll('.word,.bracket').forEach(x=>x.classList.add('used'));addLog('ТОЧНОЕ СОВПАДЕНИЕ','success');addLog(`ПАРОЛЬ СТРАНИЦЫ: ${ARCHIVE_PASSWORD}`,'success');addLog('ДОСТУП РАЗРЕШЁН','success');restartButton.disabled=false;restartButton.textContent='ОТКРЫТЬ ДОСТУП';restartButton.focus();return}window.TerminalAudio?.wrong();attempts--;addLog(`СОВПАДЕНИЕ: ${similarity(word)}/${PASSWORD.length}`,'fail');updateAttempts();lockIfEmpty()}
function bonus(button,type){if(button.classList.contains('used')||attempts<=0)return;hintUses[type]++;button.classList.add('used');if(type==='trap'){window.TerminalAudio?.wrong();attempts--;updateAttempts();addLog('ЛОЖНАЯ ПОДСКАЗКА: ПОПЫТКА ПОТЕРЯНА','fail');lockIfEmpty();return}window.TerminalAudio?.hint();if(type==='remove'){const possible=candidates.filter(x=>x!==PASSWORD&&!used.has(x)&&!duds.has(x));if(!possible.length){addLog('НЕТ ДОСТУПНЫХ ЛОЖНЫХ СЛОВ');return}const dud=possible[Math.floor(Math.random()*possible.length)];duds.add(dud);document.querySelectorAll(`[data-word="${dud}"]`).forEach(x=>x.classList.add('used'));addLog(`ЛОЖНОЕ СЛОВО УДАЛЕНО: ${dud}`,'success');return}const hidden=Array.from({length:PASSWORD.length},(_,i)=>i).filter(i=>!revealed.has(i));if(!hidden.length){addLog(`КОДОВОЕ СЛОВО УЖЕ РАСКРЫТО: ${PASSWORD}`,'success');return}const position=hidden[Math.floor(Math.random()*hidden.length)];revealed.add(position);addLog(`ФРАГМЕНТ КОДОВОГО СЛОВА: ${passwordMask()}`,'success')}
function bind(){dump.querySelectorAll('.word').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.word,b)));dump.querySelectorAll('.bracket').forEach(b=>b.addEventListener('click',()=>bonus(b,b.dataset.hint)))}
function passwordMask(){return [...PASSWORD].map((c,i)=>revealed.has(i)?c:'#').join('')}
const restartButton=document.getElementById('restartHack');
function startHack(){attempts=MAX_ATTEMPTS;used.clear();duds.clear();revealed.clear();hintUses={remove:0,reveal:0,trap:0};dumpRefreshed=false;accessGranted=false;restartButton.disabled=false;restartButton.textContent='НОВЫЙ ДАМП';log.innerHTML='<p>&gt; НОВЫЙ СЕАНС ВЗЛОМА</p>';updateAttempts();build();bind()}
function refreshDump(){if(dumpRefreshed)return;dumpRefreshed=true;restartButton.disabled=true;const restored=Math.min(2,MAX_ATTEMPTS-attempts);attempts+=restored;updateAttempts();const hintCount=Object.values(hintUses).reduce((sum,n)=>sum+n,0);log.innerHTML='<p>&gt; ДАМП ПАМЯТИ ОБНОВЛЁН</p>';addLog(`ВОССТАНОВЛЕНО ПОПЫТОК: ${restored}`,'success');addLog(`ПОТРАЧЕНО СЛОВ: ${used.size}`);addLog(`ИСПОЛЬЗОВАНО ПОДСКАЗОК: ${hintCount}`);if(revealed.size)addLog(`СОХРАНЁННЫЙ ФРАГМЕНТ: ${passwordMask()}`,'success');build();bind()}
function showVault(){document.getElementById('hackView').classList.add('hidden');document.getElementById('vaultView').classList.remove('hidden');window.scrollTo(0,0)}
const accessDialog=document.getElementById('accessDialog'),choicePanel=document.getElementById('choicePanel'),passwordPanel=document.getElementById('passwordPanel'),passwordInput=document.getElementById('passwordInput'),passwordError=document.getElementById('passwordError');
function openGateway(){document.getElementById('hackView').classList.add('hidden');document.getElementById('vaultView').classList.add('hidden');choicePanel.classList.remove('hidden');passwordPanel.classList.add('hidden');passwordInput.value='';passwordError.textContent='';if(!accessDialog.open)accessDialog.showModal()}
document.getElementById('passwordChoice').addEventListener('click',()=>{choicePanel.classList.add('hidden');passwordPanel.classList.remove('hidden');passwordInput.focus()});
document.getElementById('backChoice').addEventListener('click',()=>{passwordPanel.classList.add('hidden');choicePanel.classList.remove('hidden');passwordError.textContent=''});
document.getElementById('hackChoice').addEventListener('click',()=>{accessDialog.close();document.getElementById('hackView').classList.remove('hidden');startHack()});
passwordPanel.addEventListener('submit',e=>{e.preventDefault();if(passwordInput.value.trim().toLowerCase()===ARCHIVE_PASSWORD){accessDialog.close();showVault()}else{passwordError.textContent='ОТКАЗ: НЕВЕРНЫЙ ПАРОЛЬ';passwordInput.select()}});
accessDialog.addEventListener('cancel',e=>{e.preventDefault();location.href='fourth.html'});
restartButton.addEventListener('click',()=>accessGranted?showVault():refreshDump());
window.addEventListener('pageshow',openGateway);
